const pretty=(s:string)=>s.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
function cell(value:any,key:string){if(value==null||value==='')return '—';if(key.endsWith('_minor'))return (Number(value)/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});if(typeof value==='object')return JSON.stringify(value);return String(value);}
const labelFor=(r:RecordRow)=>[r.staff_number||r.asset_tag||r.code||r.vote_code||r.reference||r.requisition_no||r.registration_no,r.full_name||r.title||r.name||r.legal_name||r.description,r.amount_minor!=null?cell(r.amount_minor,'amount_minor'):null,r.status,r.currency].filter(Boolean).join(' · ')||r.id;
function csvDownload(rows:RecordRow[],columns:string[],name:string){
 const escape=(v:any)=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s=`'${s}`;return `"${s.replaceAll('"','""')}"`;};
 const blob=new Blob(['\uFEFF'+[columns,...rows.map(r=>columns.map(c=>cell(r[c],c)))].map(r=>r.map(escape).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`fda-${name}.csv`;a.click();URL.revokeObjectURL(url);
}
function Lookup({field,value,onChange,api}:{field:Field;value:string;onChange:(v:string)=>void;api:Api}){
 const [options,setOptions]=useState<RecordRow[]>([]),[query,setQuery]=useState(''),[error,setError]=useState('');
 useEffect(()=>{let current=true;const timer=setTimeout(()=>{void api<any>(`${field.lookup}${field.lookup!.includes('?')?'&':'?'}limit=100&q=${encodeURIComponent(query)}`).then(r=>{if(current){setOptions(Array.isArray(r)?r.filter(x=>labelFor(x).toLowerCase().includes(query.toLowerCase())):r.rows);setError('');}}).catch(e=>{if(current)setError(e.message);});},200);return()=>{current=false;clearTimeout(timer);};},[field.lookup,query,api]);
 return <div className="space-y-1"><input aria-label={`Search ${field.label}`} placeholder={`Search ${field.label.toLowerCase()}…`} value={query} onChange={e=>setQuery(e.target.value)} className="input text-xs"/><select required={!field.optional} className="input" value={value||''} onChange={e=>onChange(e.target.value)}><option value="">Select {field.label.toLowerCase()}</option>{options.map(r=><option key={r.id} value={r.id}>{labelFor(r)}</option>)}</select>{error&&<p role="alert" className="text-xs text-red-700">{error}</p>}</div>;
}
function JournalLines({value,onChange,api}:{value:any;onChange:(v:any)=>void;api:Api}){
 const lines:RecordRow[]=Array.isArray(value)?value:[{accountId:'',debit:'',credit:''},{accountId:'',debit:'',credit:''}];
 const set=(i:number,k:string,v:string)=>onChange(lines.map((l,index)=>index===i?{...l,[k]:v}:l));
 return <div className="space-y-3">{lines.map((l,i)=><div key={i} className="border rounded-lg p-3 grid grid-cols-2 gap-2"><div className="col-span-2"><Lookup api={api} field={lookup('accountId','Ledger account','/api/finance/accounts')} value={l.accountId} onChange={v=>set(i,'accountId',v)}/></div>{['debit','credit'].map(k=><label key={k} className="text-xs">{pretty(k)}<input className="input" type="number" step="0.01" min="0" value={l[k]} onChange={e=>set(i,k,e.target.value)}/></label>)}{lines.length>2&&<button type="button" className="text-xs text-red-700" onClick={()=>onChange(lines.filter((_,index)=>index!==i))}>Remove line</button>}</div>)}<button type="button" className="text-sm font-bold text-forest-800" onClick={()=>onChange([...lines,{accountId:'',debit:'',credit:''}])}>+ Add journal line</button><p className="text-xs text-slate-500">Each line must contain a debit or a credit. The server checks exact balance before saving.</p></div>;
}
function DataForm({fields,values,setValues,api}:{fields:Field[];values:RecordRow;setValues:(v:RecordRow)=>void;api:Api}){
 return <>{fields.map(f=><label key={f.key} className="block text-sm font-semibold">{f.label}{f.optional&&<span className="font-normal text-slate-400"> (optional)</span>}<div className="mt-1">{f.lookup?<Lookup field={f} api={api} value={values[f.key]} onChange={v=>setValues({...values,[f.key]:v})}/>:f.type==='journal'?<JournalLines api={api} value={values[f.key]} onChange={v=>setValues({...values,[f.key]:v})}/>:f.options?<select required={!f.optional} className="input" value={values[f.key]||''} onChange={e=>setValues({...values,[f.key]:e.target.value})}><option value="">Select…</option>{f.options.map(v=><option key={v} value={v}>{pretty(v)}</option>)}</select>:f.type==='textarea'?<textarea required={!f.optional} maxLength={f.maxLength||2000} rows={3} className="input" value={values[f.key]||''} onChange={e=>setValues({...values,[f.key]:e.target.value})}/>:f.type==='checkbox'?<input required type="checkbox" checked={values[f.key]===true} onChange={e=>setValues({...values,[f.key]:e.target.checked})}/>:<input required={!f.optional} className="input" type={f.type||'text'} step={f.type==='number'?(/quantity|reorderpoint/i.test(f.key)?'0.001':'0.01'):undefined} maxLength={240} value={values[f.key]??''} onChange={e=>setValues({...values,[f.key]:e.target.value})}/>}</div></label>)}</>;
}
